using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class AttributedTypeGeneratedFormatterTests(ITestOutputHelper logger)
{
    [Fact]
    public async Task MessagePackObjectAttributesOnFormattedType_AreHonoured()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [MessagePackObject]
                public class MyObject
                {
                    [Key(0)]
                    public int Id { get; set; }

                    [Key(1)]
                    public string Label { get; set; }

                    [IgnoreMember]
                    public string Secret { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class MyObjectCustomFormatter : IMessagePackFormatter<MyObject>
                {
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }
            }
            """;
        string formatterSource = await this.GetCustomFormatterSourceAsync(source);
        Assert.DoesNotContain("Secret", formatterSource);
        Assert.Contains("WriteArrayHeader", formatterSource);
    }

    [Fact]
    public async Task DataContractAttributesOnFormattedType_AreHonoured()
    {
        string source = """
            using System.Runtime.Serialization;
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [DataContract]
                public class MyObject
                {
                    [DataMember(Order = 0)]
                    public int Id { get; set; }

                    [DataMember(Order = 1)]
                    public string Label { get; set; }

                    public string Unlisted { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class MyObjectCustomFormatter : IMessagePackFormatter<MyObject>
                {
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }
            }
            """;
        string formatterSource = await this.GetCustomFormatterSourceAsync(source);
        Assert.DoesNotContain("Unlisted", formatterSource);
    }

    private async Task<string> GetCustomFormatterSourceAsync(string source)
    {
        CSharpParseOptions parseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.CSharp12);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = new(framework)
        {
            MetadataReference.CreateFromFile(typeof(MessagePack.KeyAttribute).Assembly.Location),
            MetadataReference.CreateFromFile(typeof(MessagePack.MessagePackSerializer).Assembly.Location),
        };

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, allowUnsafe: true));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        foreach (Diagnostic d in generatorDiagnostics)
        {
            logger.WriteLine(d.ToString());
        }

        List<string> generated = driver.GetRunResult().Results.SelectMany(r => r.GeneratedSources).Select(s => s.SourceText.ToString()).ToList();
        foreach (string text in generated)
        {
            logger.WriteLine(text);
        }

        string? formatterSource = generated.FirstOrDefault(t => t.Contains("MyObjectCustomFormatter") && t.Contains("Deserialize("));
        Assert.NotNull(formatterSource);
        return formatterSource!;
    }
}
